    "oneLine": "Hồng ngọc của hồ Nhật Nguyệt, lai giữa trà dại Đài Loan và assamica Miến Điện — lá lớn oxy hóa dài thở ra bạc hà, quế và nhục đậu khấu, dư vị dài.",
