    "process": "Làm héo → sao → vò → ốc đôi (wo dui: độ ẩm 30–40%, 50–65 °C, 40–70 ngày) → sấy khô → ép bánh.",
    "story": "Nhà máy trà Côn Minh phát triển kỹ thuật ốc đôi (wo dui) năm 1973 để rút ngắn thời gian chờ.",
